"""Demo: the sharp threshold constant c_k and the exponent-density duality."""
from __future__ import annotations
import math


def game_exponent(k: float) -> float:
    return (k - 2.0) / (k - 1.0)


def max_density(k: float) -> float:
    return (k - 1.0) / (k - 2.0)


def threshold_const(k: int) -> float:
    log_base = math.log(k - 1.0) + (k - 2) * math.log(2.0 * (k - 1.0) / k)
    return math.exp(log_base / (k - 1.0))


if __name__ == "__main__":
    for k in [4, 5, 6, 10, 100, 1000]:
        a, m, c = game_exponent(k), max_density(k), threshold_const(k)
        print(f"k={k:>5}  exp={a:.5f}  c_k={c:.4f}  m2={m:.5f}  exp*m2={a*m:.6f}")

"""Demo: verify m_2(C_k) = (k-1)/(k-2) by enumerating subgraph shapes."""
from __future__ import annotations
from typing import Tuple


def cycle_max_density(k: int) -> Tuple[float, str]:
    best, name = -float("inf"), ""
    # whole cycle: e = v = k
    d = (k - 1) / (k - 2)
    if d > best:
        best, name = d, "whole cycle"
    # proper subgraphs are linear forests: v vertices, c paths, e = v - c edges
    for v in range(3, k + 1):
        for c in range(1, v):
            e = v - c
            if e < 1:
                continue
            d = (e - 1) / (v - 2)
            if d > best:
                best, name = d, f"forest v={v}, {c} paths"
    return best, name


if __name__ == "__main__":
    for k in [4, 5, 6, 8, 12]:
        val, who = cycle_max_density(k)
        print(f"k={k:>3}: max 2-density {val:.5f} at [{who}]  formula {(k-1)/(k-2):.5f}")

